#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, h;
    vector<string> line;
    string input_line;
    getline(cin, input_line);
    stringstream ss(input_line);
    string token;
    vector<int> line_vals;
    while (ss >> token) {
        line_vals.push_back(stoi(token));
    }
    n = line_vals[0];
    h = line_vals[1];

    vector<vector<long long>> array_nodes_minheight(36, vector<long long>(36, 0));
    array_nodes_minheight[0][0] = 1;

    for (int nodes = 1; nodes < 36; ++nodes) {
        for (int minheight = 0; minheight <= nodes; ++minheight) {
            for (int topnode = 1; topnode <= nodes; ++topnode) {
                int left = topnode - 1;
                int right = nodes - topnode;
                long long left_zero = array_nodes_minheight[left][0];
                long long right_zero = array_nodes_minheight[right][0];
                long long left_min = array_nodes_minheight[left][max(minheight - 1, 0)];
                long long right_min = array_nodes_minheight[right][max(minheight - 1, 0)];
                array_nodes_minheight[nodes][minheight] += left_zero * right_zero - (left_zero - left_min) * (right_zero - right_min);
            }
        }
    }

    cout << array_nodes_minheight[n][h] << "\n";

    return 0;
}
